(()=>{'use strict';const game=document.body.dataset.game;if(!['runner','jet'].includes(game))return;let previous='start',run=null,finished=false,pending=null,closed=false;const abort=new AbortController();const read=()=>{try{return localStorage.getItem('arcade-player-name')||''}catch{return ''}};const box=document.createElement('div');box.className='online-board-tools';box.innerHTML='<button id="online-board-open">🏆 線上排行榜</button>';document.body.append(box);const dialog=document.createElement('dialog');dialog.className='online-board';dialog.innerHTML='<button class="board-close" aria-label="關閉">×</button><small>SHARED ONLINE · ALL PLAYERS</small><h2>一局一紀錄</h2><label>公開暱稱 <input id="board-name" maxlength="20" placeholder="玩家" autocomplete="off"></label><p class="board-disclosure">每局結束會公開暱稱、分數、距離及遊玩時間。請勿填真名或私人資料。</p><div class="board-tabs"><button data-board-view="top">最高分</button><button data-board-view="recent">最新每局</button><button id="board-refresh">重新整理</button></div><p id="board-status" role="status"></p><ol id="board-list"></ol><button id="board-delete">刪除此瀏覽器的線上紀錄</button>';document.body.append(dialog);const name=dialog.querySelector('input');name.value=read()||'玩家'+Math.floor(1000+Math.random()*9000);let view='top';const notice=document.createElement('div');notice.id='online-save-status';notice.setAttribute('role','status');box.append(notice);const on=(el,type,fn)=>el.addEventListener(type,fn,{signal:abort.signal});const call=async(path,body)=>{const res=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'content-type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:abort.signal});const data=await res.json();if(!res.ok)throw Error(data.error||'未能連線');return data};
async function load(){const status=dialog.querySelector('#board-status'),list=dialog.querySelector('ol');status.textContent='載入共同排行榜…';list.replaceChildren();try{const data=await call('leaderboard?game='+game+'&view='+view);for(const [i,e]of data.entries.entries()){const li=document.createElement('li'),who=document.createElement('strong'),result=document.createElement('span');who.textContent=(i+1)+'. '+e.player;result.textContent=e.score+' 分 · '+e.distance+'m · '+(e.duration/1000).toFixed(1)+'s · '+({easy:'輕鬆',medium:'標準',hard:'挑戰',standard:'標準'}[e.difficulty]||'標準')+' · '+new Date(e.finished_at).toLocaleDateString();li.append(who,result);list.append(li)}status.textContent=data.entries.length?'所有玩家共享 · 最近更新 '+new Date().toLocaleTimeString():'暫時未有成績，完成第一局吧。'}catch(e){status.textContent='未能載入：'+e.message}}
on(document.getElementById('online-board-open'),'click',()=>{if(window.detailedGameSnapshot?.().state==='playing')window.dispatchEvent(new KeyboardEvent('keydown',{code:'KeyP',key:'p'}));dialog.showModal();load()});on(dialog.querySelector('.board-close'),'click',()=>dialog.close());on(name,'change',()=>{try{localStorage.setItem('arcade-player-name',name.value)}catch{}});on(dialog.querySelector('#board-refresh'),'click',load);on(dialog.querySelector('#board-delete'),'click',async()=>{if(!confirm('刪除此瀏覽器發佈的全部線上成績？'))return;try{await fetch('/api/runs/mine',{method:'DELETE',signal:abort.signal});load()}catch{dialog.querySelector('#board-status').textContent='未能刪除，請再試。'}});dialog.querySelectorAll('[data-board-view]').forEach(b=>on(b,'click',()=>{view=b.dataset.boardView;load()}));
async function start(){finished=false;run=null;notice.textContent='線上紀錄連線中';pending=call('runs/start',{game,player:name.value,difficulty:window.detailedUIState?.difficulty||'standard'}).then(r=>{run=r.id;notice.textContent='本局結束後公開成績';return r}).catch(e=>{notice.textContent='本局未連上排行榜；仍可遊玩。';return null})}
async function finish(s){if(finished)return;finished=true;const session=await pending;const id=session?.id;if(!id||closed)return;try{await call('runs/finish',{id,score:Math.floor(s.score),distance:s.distance||0,duration:game==='runner'?s.powers.time:s.seconds});if(run===id)notice.textContent='✓ 本局已加入共同排行榜'}catch(e){if(run===id)notice.textContent='成績未能上傳：'+e.message}}
const timer=setInterval(()=>{const s=window.detailedGameSnapshot?.();if(!s)return;if(s.state==='playing'&&['start','menu','gameover','gameOver'].includes(previous))start();if(['gameOver','gameover'].includes(s.state)&&!['gameOver','gameover'].includes(previous))finish(s);previous=s.state},100);on(window,'pagehide',()=>{const s=window.detailedGameSnapshot?.();if(!finished&&run&&s){navigator.sendBeacon('/api/runs/finish',new Blob([JSON.stringify({id:run,score:Math.floor(s.score),distance:s.distance||0,duration:game==='runner'?s.powers.time:s.seconds})],{type:'application/json'}))}closed=true;clearInterval(timer);abort.abort()});window.onlineLeaderboardStatus=()=>({game,run,finished,status:notice.textContent});})();
